        "lingua_originale": "it",
        "titolo_orig": "BLOCCO",
        "testo_it": "USA: bombardamenti sull'Iran continueranno per un mese, la guerra è quasi finita.",
        "priorita": "Alta",
        "id_gruppo": 1,
        "link": "https://www.internazionale.it/opinione/giovanni-de-mauro/2026/04/15/blocco",
